using System.Reflection;
using System.Runtime.Loader;

using Hexalith.EventStore.Contracts.Routing;
using Hexalith.EventStore.DomainService;
using Hexalith.EventStore.ServiceDefaults.Routing;

using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.AspNetCore.Routing;
using Microsoft.AspNetCore.Authorization;
using Hexalith.EventStore.ServiceDefaults.Authentication;
using Hexalith.EventStore.Contracts.Authorization;

namespace Hexalith.EventStore.Server.Routing;

/// <summary>Binds the gateway to exact compiled owners and pre-generated bytes from its private Development composition.</summary>
public static class RunScopedRouteCatalogGateway
{
    /// <summary>Observes actual technical gateway endpoint policies without deriving operation eligibility from them.</summary>
    public static string? Operation(RouteEndpoint endpoint)
    {
        ArgumentNullException.ThrowIfNull(endpoint);
        string path = (endpoint.RoutePattern.RawText ?? string.Empty).Trim('/');
        var policies = endpoint.Metadata.GetOrderedMetadata<IAuthorizeData>().Select(data => data.Policy).ToArray();
        foreach (string? policy in policies)
            foreach (string scheme in new[] { "DaprInternal", RouteCatalogEndpointExtensions.WorkloadScheme })
                if (policy?.StartsWith(scheme + ":", StringComparison.Ordinal) == true) return policy[(scheme.Length + 1)..];
        if (!policies.Contains(EventStoreHttpHostSecurityExtensions.HumanPolicy, StringComparer.Ordinal)) return null;
        return path switch
        {
            "api/v1/commands" => EventStoreOperationIdentifiers.GatewayCommandSubmit,
            "api/v1/queries" => "eventstore:query-read",
            "api/v1/routing/catalog" => "eventstore:catalog-metadata-read",
            "api/v1/streams/read" => EventStoreOperationIdentifiers.GatewayStreamRead,
            _ => null,
        };
    }
    /// <summary>Loads mapped owner adapter factories and independently captures installed operations and policies.</summary>
    public static IServiceCollection AddEventStoreRunScopedCatalogGateway(this IServiceCollection services, IConfiguration configuration)
    {
        ArgumentNullException.ThrowIfNull(services);
        ArgumentNullException.ThrowIfNull(configuration);
        var section = configuration.GetSection("EventStore:RouteCatalog:DevelopmentBootstrap");
        if (string.IsNullOrEmpty(section["Directory"])) return services;
        var owners = Load(section.GetSection("OwnerAssemblies").Get<string[]>() ?? []);
        var adapters = Load(section.GetSection("AdapterAssemblies").Get<string[]>() ?? []);
        if (owners.Length == 0 || adapters.Length == 0) throw new RouteCatalogUnavailableException("Mapped owner schemas and adapter assemblies are required.");
        foreach (var factory in adapters.SelectMany(a => a.GetCustomAttributes<RouteCatalogAdapterSourceAttribute>()))
        {
            if (factory.SourceType.GetMethod("Create", BindingFlags.Public | BindingFlags.Static)?.Invoke(null, null)
                is not IEnumerable<IDeclaredIdempotencyIntentAdapter> declared)
                throw new RouteCatalogUnavailableException($"The owner adapter factory {factory.SourceType.FullName} is unavailable.");
            foreach (var adapter in declared) services.AddSingleton<IIdempotencyIntentAdapter>(adapter);
        }
        return services.AddEventStoreDevelopmentRouteCatalogBootstrap(configuration, async (provider, token) =>
        {
            var fence = provider.GetRequiredService<FiniteRouteCatalogReceiver>();
            await fence.WaitForCaptureAsync(token).ConfigureAwait(false);
            var receiver = fence.Observe();
            var actual = await DevelopmentRouteCatalogInputs.CaptureAsync(configuration, "eventstore",
                CompiledRouteCatalogDeclarations.Read(owners), [], await RouteCatalogAdmissionObservation.CaptureAsync(provider, "eventstore", token).ConfigureAwait(false), [],
                receiver.Endpoints.Where(e => e.Admitted).Select(e => new RouteCatalogAuxiliaryOperation("eventstore", e.Pattern.TrimStart('/'), e.Operation!, "gateway")).ToArray(), token).ConfigureAwait(false);
            return actual with { ReceiverSurface = receiver, Operations = CompiledRouteCatalogDeclarations.ReadOperations(owners) };
        }, _ => RouteCatalogCodec.Decode(File.ReadAllBytes(section["CatalogPath"]!), section["RootDigest"]));
    }

    private static Assembly[] Load(IEnumerable<string> paths) => paths.Select(path =>
    {
        if (!Path.IsPathFullyQualified(path) || !File.Exists(path)) throw new RouteCatalogUnavailableException("A mapped owner assembly is unavailable.");
        AssemblyLoadContext.Default.Resolving += (context, name) =>
        {
            string dependency = Path.Combine(Path.GetDirectoryName(path)!, name.Name + ".dll");
            return File.Exists(dependency) ? context.LoadFromAssemblyPath(dependency) : null;
        };
        return AssemblyLoadContext.Default.LoadFromAssemblyPath(path);
    }).Distinct().ToArray();
}
